// Analyze spreads and opportunities
const btc = $('Get BTC').first().json;
const eth = $('Get ETH').first().json;
const sol = $('Get SOL').first().json;

function analyzeSpread(data, pair) {
  const ticker = data.tickers?.[pair] || data.tickers?.[Object.keys(data.tickers || {})[0]];
  if (!ticker) return null;

  const bid = parseFloat(ticker.bid);
  const ask = parseFloat(ticker.ask);
  const price = parseFloat(ticker.price);
  const volume = parseFloat(ticker.volume_24h);

  const spread = ask - bid;
  const spreadBps = (spread / price) * 10000;

  const volumeScore = Math.min(volume / 1000, 1);
  const opportunityScore = spreadBps * volumeScore;

  return {
    pair: pair.replace('XXBT', 'BTC').replace('XETH', 'ETH').replace('ZUSD', '/USD'),
    price,
    bid,
    ask,
    spread,
    spread_bps: spreadBps,
    volume_24h: volume,
    opportunity_score: opportunityScore,
    is_opportunity: spreadBps > 10
  };
}

const opportunities = [
  analyzeSpread(btc, 'XXBTZUSD'),
  analyzeSpread(eth, 'XETHZUSD'),
  analyzeSpread(sol, 'SOLUSD')
].filter(x => x !== null);

opportunities.sort((a, b) => b.opportunity_score - a.opportunity_score);

const hasOpportunity = opportunities.some(o => o.is_opportunity);
const bestOpportunity = opportunities[0];

return [{
  json: {
    timestamp: new Date().toISOString(),
    has_opportunity: hasOpportunity,
    best_opportunity: bestOpportunity,
    all_spreads: opportunities,
    summary: hasOpportunity 
      ? `Spread opportunity: ${bestOpportunity.pair} at ${bestOpportunity.spread_bps.toFixed(1)} bps`
      : `No opportunities. Best spread: ${bestOpportunity?.pair} at ${bestOpportunity?.spread_bps.toFixed(1)} bps`
  }
}];

const data = $input.first().json;
console.log('=== SPREAD OPPORTUNITY DETECTED ===');
console.log('Best:', data.best_opportunity.pair);
console.log('Spread:', data.best_opportunity.spread_bps.toFixed(1), 'bps');
return [{ json: { alert_type: 'spread_opportunity', ...data } }];

const data = $input.first().json;
console.log('=== SPREAD SCAN: No opportunities ===');
console.log(data.summary);
return [{ json: { logged: true, summary: data.summary } }];
